var reultJson=[];
var AddTab =function(title,listMap,url){
    if(title!=='')AddSingleTab(title,'');
    for (var key in listMap) {
        if (listMap.hasOwnProperty(key)) {
            tempContent=JSON.parse(JSON.stringify(defaultContent));
            tempContent.title=key;
            tempContent.url=url.replace('UID',listMap[key]);
            reultJson.push(tempContent);
        }
    }
}
var AddSingleTab =function(title,url){
    tempTitle=JSON.parse(JSON.stringify(defaultTitle));
    tempTitle.title=title;
    tempTitle.url=url;
    reultJson.push(tempTitle);
}

AddTab("༺ˇ»`ʚ榜单ɞ´«ˇ༻",tab1,url1[0]);
